from collections import deque

def solve(n, edges):
    def build_graph(n, edges):
        graph = [[] for _ in range(n)]
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)
        return graph

    def bfs(start, graph, visited):
        queue = deque([start])
        visited.add(start)
        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)

    graph = build_graph(n, edges)
    visited = set()
    components = 0

    for i in range(n):
        if i not in visited:
            components += 1
            bfs(i, graph, visited)

    return components
