from collections import deque

def solve(n, edges):
    def bfs(start, visited, adj):
        queue = deque([start])
        visited[start] = True
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    queue.append(v)

    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    visited = [False] * n
    count = 0

    for i in range(n):
        if not visited[i]:
            bfs(i, visited, adj)
            count += 1

    return count
