def solve(n, edges, s, t):
    # Create adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # To handle negative weights, we use Bellman-Ford
    # Since weights are non-negative, Dijkstra could work too, but Bellman-Ford is easier for all cases
    # We will use Bellman-Ford to find the shortest path from s to t

    # Initialize distance array
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for i in range(n - 1):
        updated = False
        for u in range(n):
            if dist[u] == float('inf'):
                continue
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    updated = True
        if not updated:
            break

    # Check if t is reachable
    if dist[t] == float('inf'):
        return -1
    return dist[t]
