def solve(n, edges, s, t):
    from collections import defaultdict, deque

    if s == t:
        return 0

    # Build the graph
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # Bellman-Ford algorithm to detect shortest paths
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for i in range(n - 1):
        updated = False
        for u in graph:
            for v, w in graph[u]:
                if dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w
                    updated = True
        if not updated:
            break

    # Check if t is reachable
    if dist[t] == float('inf'):
        return -1
    return dist[t]
