    from collections import defaultdict, deque

    if s == t:
        return 0

    # Build adjacency list
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # Bellman-Ford algorithm to detect shortest paths
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for _ in range(n - 1):
        for u in range(n):
            if dist[u] == float('inf'):
                continue
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w

    # Check for negative weight cycles (not needed for this problem as weights are non-negative)
    # But for completeness, we can check
    for u in range(n):
        if dist[u] == float('inf'):
            continue
        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                # If there's a negative cycle, return -1
                return -1

    return dist[t] if dist[t] != float('inf') else -1
