    from collections import defaultdict, deque

    if s == t:
        return 0

    # Build adjacency list with weights
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # Bellman-Ford to detect negative cycles and find shortest paths
    # We will use a modified version to detect reachability and find shortest path
    # since the graph can have cycles, we need to check if t is reachable from s

    # Initialize distance array
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for i in range(n - 1):
        for u in graph:
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w

    # Check for negative cycles that are reachable from s
    in_queue = [False] * n
    queue = deque()
    for u in graph:
        if dist[u] != float('inf'):
            queue.append(u)
            in_queue[u] = True

    while queue:
        u = queue.popleft()
        in_queue[u] = False
        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                if not in_queue[v]:
                    queue.append(v)
                    in_queue[v] = True
                # If we detect a negative cycle containing t, then it's unreachable
                if dist[v] == float('inf'):
                    continue
                dist[v] = dist[u] + w

    # If t is not reachable, return -1
    if dist[t] == float('inf'):
        return -1
