    dist = [INF] * n
    dist[s] = 0
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Bellman-Ford to detect negative cycles and find shortest paths
    for i in range(n):
        for u in range(n):
            if dist[u] == INF:
                continue
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
        # If we're on the nth iteration, there's a negative cycle
