def solve(n, edges, s, t):
    from collections import deque

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Bellman-Ford algorithm to detect negative cycles and find shortest path
    # Initialize distance array
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for i in range(n-1):
        updated = False
        for u in range(n):
            for v, w in adj[u]:
                if dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w
                    updated = True
        if not updated:
            break

    # Check for negative weight cycles that are reachable from s
    for u in range(n):
        for v, w in adj[u]:
            if dist[u] + w < dist[v]:
                # If t is reachable from s via negative cycle, it's not bounded
                if dist[t] != float('inf'):
                    return -1

    if dist[t] == float('inf'):
        return -1
    return dist[t]
