    def build_graph():
        graph = defaultdict(list)
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)
        return graph

    def dfs(node, visited):
        if node in visited:
            return
        visited.add(node)
        for neighbor in graph[node]:
            dfs(neighbor, visited)

    graph = build_graph()
    visited = set()
    components = 0

    for i in range(n):
        if i not in visited:
            dfs(i, visited)
            components += 1

    return components
```

