        def __init__(self, n):
            self.adj = [[] for _ in range(n)]

        def add_edge(self, u, v):
            self.adj[u].append(v)
            self.adj[v].append(u)

        def dfs(self, node, visited):
            visited.add(node)
            for neighbor in self.adj[node]:
                if neighbor not in visited:
                    self.dfs(neighbor, visited)

        def count_components(self):
            visited = set()
            count = 0
            for i in range(n):
                if i not in visited:
                    self.dfs(i, visited)
                    count += 1
            return count

    graph = Graph(n)
    for u, v in edges:
        graph.add_edge(u, v)
    return graph.count_components()
