from collections import deque

def solve(n, edges, s, t):
    if s == t:
        return 0

    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    dist = [float('inf')] * n
    dist[s] = 0
    visited = [False] * n

    queue = deque([s])
    visited[s] = True

    while queue:
        u = queue.popleft()
        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                if not visited[v]:
                    visited[v] = True
                    queue.append(v)

    return dist[t] if dist[t] != float('inf') else -1
