def solve(n, edges, s, t):
    from collections import deque

    if s == t:
        return 0

    # Build the adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Bellman-Ford algorithm to find shortest path from s to t
    # since n is small (<= 100), this is acceptable
    dist = [float('inf')] * n
    dist[s] = 0

    for _ in range(n - 1):
        for u in range(n):
            if dist[u] == float('inf'):
                continue
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w

    if dist[t] == float('inf'):
        return -1
    return dist[t]
